POST {{ORCHESTRATOR_URL}}/admin/hooks/self-sign-token/cert-as-public-key/47
(Save to brimma-wq-stage-cert.pem)
KEY_NAME=jwt-signing-key-wilqo-prod
 az keyvault key download --vault-name $KV_NAME --name $KEY_NAME  --file stage-public-signing.pem
openssl x509 -in brimma-wq-stage-cert.pem -pubkey -noout > stage-cert-public.pem
openssl rsa -pubin -in stage-cert-public.pem -modulus -noout
openssl rsa -pubin -in stage-public-signing.pem -modulus -noout



